/** Do not treat a generic type argument as an export name. A check that is not this analyzer is refused. */
export function genericAngles(text: string): string | null {
  if (!text.includes("function _extractExtraNames(")) return null; // ml-guard:angle
  if (text !== ANALYZE_OLD) return null;
  return ANALYZE_NEW;
}

/** Start the proxy body when the socket is assigned. A check that is not the stream middleware is refused. */
export function bodyOnSocket(text: string): string | null {
  if (!text.includes("export const stream = defineProxyMiddleware(")) return null; // hx-guard:socket
  if (text !== WEB_OLD) return null;
  return WEB_NEW;
}

/** Do not write a Node response that has already ended. A check that is not sendNodeResponse is refused. */
export function skipEndedResponse(text: string): string | null {
  if (!text.includes("function _sendNodeResponse(")) return null; // sx-guard:ended
  if (text !== SEND_OLD) return null;
  return SEND_NEW;
}

export interface Batch19Input {
  root: string;
  output: string;
  sourcePattern?: string;
  nodePath: string;
  nodeModules?: string | null;
  testCommand: readonly string[];
  bwrap?: string;
}

function readLocal(root: string, path: string): string | null {
  try { return readFileSync(join(root, path), "utf8"); } catch { return null; }
}

function filesOf(root: string, pattern: string | undefined): string[] {
  const listed = practiceGit(root, ["ls-files"]);
  if (!listed.ok) return [];
  return listed.out.split("\n").map((p) => p.trim()).filter((p) => /\.tsx?$/.test(p) && !p.endsWith(".d.ts") && (!pattern || new RegExp(pattern).test(p)));
}

/** Apply the one repair the failure can prove, then require the published test to pass in the sandbox. */
export function repairBatch19(input: Batch19Input): { diff: string; file: string } | null {
  if (!/Error|not equal|Expected|Invalid|fail|toEqual|HEADERS_SENT|WRITE_AFTER_END/i.test(input.output)) return null;
  const edits: { path: string; next: string; original: string }[] = [];
  for (const path of filesOf(input.root, input.sourcePattern)) {
    const original = readLocal(input.root, path);
    if (original === null) continue;
    const next = genericAngles(original) ?? bodyOnSocket(original) ?? skipEndedResponse(original);
    if (next && next !== original) edits.push({ path, next, original });
  }
  if (edits.length !== 1) return null;
  const edit = edits[0]!;
  try {
    writeFileSync(join(input.root, edit.path), edit.next);
    const again = runInPracticeSandbox(input.root, input.testCommand, 120_000, {
      capture: true, nodePath: input.nodePath, nodeModules: input.nodeModules, ...(input.bwrap ? { bwrap: input.bwrap } : {}),
    });
    if (again.unsafe || again.code !== 0) return null;
    const diff = practiceGit(input.root, ["diff", "--no-color", "--no-ext-diff", "--no-renames", "--", edit.path]);
    if (!diff.ok || !diff.out.trim()) return null;
    return { diff: diff.out, file: edit.path };
  } finally {
    writeFileSync(join(input.root, edit.path), edit.original);
  }
}
